local _, WFJ = ...
WFJ.Data.add("book", {
  ["c34e9175308d1246"] = { "当時Anasterian Sunstriderに率いられていたelvesは、迫り来る戦争にほとんど関心を示さなかった。しかし彼らには、Lotharを助ける義務があった。Lotharは、はるか昔にelvesを助けたArathiの血筋の最後の末裔だったからである。", "." },
  ["c388a16eb63bf39c"] = { "GurubashiとAmaniの帝国は互いをほとんど好んでいなかったが、戦争をすることはまれだった。当時、両者にとって最大の共通の敵は、第三の帝国――Azj'Aqirの文明であった。aqirは、はるか西の地を支配する知能の高い昆虫型の種族だった。この狡猾な昆虫型種族はきわめて拡張主義的で、信じがたいほど邪悪であった。aqirはKalimdorの野から昆虫以外のすべての生命を根絶することに取りつかれていた。", "." },
  ["c38c4f289103d6f3"] = { "諸氏族の間でシャーマンの信仰が衰退した責任は、Gul'danにあった。力と、敵を支配する力の約束が、彼の申し出をいっそう魅力的なものにした。Kil'jaedenの助けを得て、Gul'danは氏族を操り始めた。かつて高潔であったオークは、堕落した心なき野蛮人と化した。悪魔の血を体内に取り込んだことで、オークはさらに無慈悲で野蛮になった。", "." },
  ["c393139c7900538a"] = { "悪魔の呪いが終わった今、Hordeは好戦的な巨大勢力から、征服ではなく生存と繁栄に身を捧げる緩やかな連合へと変わった。高潔なトーレンと、Darkspear族の狡猾なトロールの助けを得て、Thrallとオークたちは自らの地での新たな平和の時代を心待ちにした。", "." },
  ["c39768280cf5ac5d"] = { "Eluneの大司祭となっていたTyrandeは、愛するMalfurionに、自分を置いてYseraのEmerald Dreamへ行かないでほしいと願った。だがMalfurionは、移ろいゆくDreamwaysに入るという誓いに縛られていたため、大司祭に別れを告げ、二人が互いの愛に忠実である限り、決して離れ離れにはならないと誓った。", "." },
  ["c3a592e04dc94a5a"] = { "Horgus the Ravagerの運命\n\nHorgus the RavagerはThe Battle of Darrowshireで倒れた。だが彼の内なる邪悪は完全には尽きていなかった。勝利したScourgeの軍勢はDarrowshireの戦場から彼の頭蓋骨を持ち去り、立ち向かってくる生者たちに恐怖を植えつけるため、それを携えて進んだ。\n\n数日後、その頭を持っていたScourgeの部隊はSilver Handのパラディンたちに打ち倒された。Horgusの頭はBlackwood Lakeへと投げ込まれた。", "." },
  ["c3cb54577f8c4203"] = { "ISALIEN\n\nナイトエルフのPriestess of the Moon\n\nIsalienは一行を離れることを決めたとき、Dire Maulへの巡礼を心に決めていた。そこは、かつてEldre'Thalasとして知られた、ナイトエルフの祖先の滅びた都である。そこには今も大いなる知識の図書館が建っており、わずかなナイトエルフたちが押し寄せる脅威を食い止めてきた聖域となっている。彼女は、自らの出自について、そしておそらくは護符の欠片についても、答えを見つけるつもりでいた。なお、彼女がFalrin Treeshaperの良き友でもあったことは記しておくべきだろう。", "." },
  ["c3de158687dd34ce"] = { "激しい気性の人間の娘Aegwynnは、Orderの承認を得て、Guardianshipの衣鉢を授けられた。Aegwynnは精力的に働き、悪魔を見つけ次第追い詰めて根絶したが、男性が支配するCouncil of Tirisfalの権威にしばしば疑問を抱いた。", "." },
  ["c3fc3c4c8a07706f"] = { "あの夜なぜ私が生き延びたのか、推し量ることしかできない。私はいつも用心深く、突きをすばやくかわし、落とし穴を跳び越えてきた。Jittersというあだ名もこの性分から来ている。だから、命を救ったのはただその用心深さの才だったのかもしれない……\n\nあるいは、瓦礫から引き抜いたScytheのおかげかもしれない。Scytheそのものではありえない。必死に逃げる途中でなくしてしまったのだから。だが、WorgenをDuskwoodに呼び寄せたのが私だとすれば、Worgenは私にまれな礼儀を示したのかもしれない。呪われるがいい。", "." },
})
